def getbands(grid):
 border=grid[0][0];vs=[j for j in range(len(grid[0])) if all(row[j]==border for row in grid)];hs=[i for i,row in enumerate(grid) if all(x==border for x in row)]
 return [[[row[c:d+1] for row in grid[a:b+1]] for c,d in zip(vs,vs[1:])] for a,b in zip(hs,hs[1:])]
def props(t,bg):
 S={(i,j) for i in range(1,len(t)-1) for j in range(1,len(t[0])-1) if t[i][j]!=bg}
 area=len(S);per=sum((i+di,j+dj) not in S for i,j in S for di,dj in [(1,0),(-1,0),(0,1),(0,-1)])
 trans=sum(t[i][j]!=t[i][j+1] for i in range(1,len(t)-1) for j in range(1,len(t[0])-2))+sum(t[i][j]!=t[i+1][j] for i in range(1,len(t)-2) for j in range(1,len(t[0])-1))
 return area,per,trans
for name,g,o in [('d1',di,do),('d2',d2i,d2o)]:
 bs=getbands(g);bg=g[1][1]
 print(name)
 for k,ts in enumerate(bs):print(k,[props(t,bg) for t in ts])

def bool_transform(grid,ops):
 border=grid[0][0];bg=grid[1][1];vs=[j for j in range(len(grid[0])) if all(row[j]==border for row in grid)];hs=[i for i,row in enumerate(grid) if all(x==border for x in row)];out=[]
 for bi,(a,b) in enumerate(zip(hs,hs[1:])):
  ts=[[r[c:d+1] for r in grid[a:b+1]] for c,d in zip(vs,vs[1:])];t=[r[:] for r in ts[0]]
  for i in range(1,len(t)-1):
   for j in range(1,len(t[0])-1):
    vals=[x[i][j] for x in ts];act=[v!=bg for v in vals];keep=any(act) if ops[bi]=='or' else all(act)
    t[i][j]=(vals[0] if vals[0]!=bg else next((v for v in vals if v!=bg),bg)) if keep else bg
  out+=t if bi==0 else t[1:]
 return out
out=bool_transform(test,['or','and','or','or'])
